#include <stdlib.h>
#include <string.h>
#include <omp.h>
#if defined(__AVX512F__) || (defined(__AVX2__) && defined(__FMA__))
#include <immintrin.h>
#endif

#define KC 256
#define NCW 256

#if defined(__AVX512F__)
#define MR 12
#define NR 32
#elif defined(__AVX2__) && defined(__FMA__)
#define MR 6
#define NR 16
#else
#define MR 4
#define NR 16
#endif

static float *Abuf = NULL, *Bbuf = NULL;
static size_t Acap = 0, Bcap = 0;

static float *ensure(float *p, size_t *cap, size_t need)
{
    if (need <= *cap) return p;
    free(p);
    size_t bytes = (need * sizeof(float) + 63) & ~(size_t)63;
    p = (float *)aligned_alloc(64, bytes);
    *cap = need;
    return p;
}

#if defined(__AVX512F__)
static void kern(int kc, const float *restrict a, const float *restrict b,
                 float *restrict c, int n, int mr, int nr, int first)
{
    __m512 acc[MR][2];
#pragma GCC unroll 12
    for (int r = 0; r < MR; r++) {
        acc[r][0] = _mm512_setzero_ps();
        acc[r][1] = _mm512_setzero_ps();
    }
    for (int k = 0; k < kc; k++) {
        __m512 b0 = _mm512_load_ps(b);
        __m512 b1 = _mm512_load_ps(b + 16);
#pragma GCC unroll 12
        for (int r = 0; r < MR; r++) {
            __m512 av = _mm512_set1_ps(a[r]);
            acc[r][0] = _mm512_fmadd_ps(av, b0, acc[r][0]);
            acc[r][1] = _mm512_fmadd_ps(av, b1, acc[r][1]);
        }
        a += MR;
        b += NR;
    }
    if (mr == MR && nr == NR) {
#pragma GCC unroll 12
        for (int r = 0; r < MR; r++) {
            float *cr = c + (size_t)r * n;
            __m512 v0 = acc[r][0], v1 = acc[r][1];
            if (!first) {
                v0 = _mm512_add_ps(v0, _mm512_loadu_ps(cr));
                v1 = _mm512_add_ps(v1, _mm512_loadu_ps(cr + 16));
            }
            _mm512_storeu_ps(cr, v0);
            _mm512_storeu_ps(cr + 16, v1);
        }
    } else {
        __mmask16 m0 = nr >= 16 ? (__mmask16)0xFFFF : (__mmask16)((1u << nr) - 1);
        __mmask16 m1 = nr >= 32 ? (__mmask16)0xFFFF
                     : nr > 16 ? (__mmask16)((1u << (nr - 16)) - 1) : (__mmask16)0;
#pragma GCC unroll 12
        for (int r = 0; r < MR; r++) {
            if (r < mr) {
                float *cr = c + (size_t)r * n;
                __m512 v0 = acc[r][0], v1 = acc[r][1];
                if (!first) {
                    v0 = _mm512_add_ps(v0, _mm512_maskz_loadu_ps(m0, cr));
                    v1 = _mm512_add_ps(v1, _mm512_maskz_loadu_ps(m1, cr + 16));
                }
                _mm512_mask_storeu_ps(cr, m0, v0);
                _mm512_mask_storeu_ps(cr + 16, m1, v1);
            }
        }
    }
}
#elif defined(__AVX2__) && defined(__FMA__)
static void kern(int kc, const float *restrict a, const float *restrict b,
                 float *restrict c, int n, int mr, int nr, int first)
{
    __m256 acc[MR][2];
#pragma GCC unroll 6
    for (int r = 0; r < MR; r++) {
        acc[r][0] = _mm256_setzero_ps();
        acc[r][1] = _mm256_setzero_ps();
    }
    for (int k = 0; k < kc; k++) {
        __m256 b0 = _mm256_load_ps(b);
        __m256 b1 = _mm256_load_ps(b + 8);
#pragma GCC unroll 6
        for (int r = 0; r < MR; r++) {
            __m256 av = _mm256_broadcast_ss(a + r);
            acc[r][0] = _mm256_fmadd_ps(av, b0, acc[r][0]);
            acc[r][1] = _mm256_fmadd_ps(av, b1, acc[r][1]);
        }
        a += MR;
        b += NR;
    }
    if (mr == MR && nr == NR) {
#pragma GCC unroll 6
        for (int r = 0; r < MR; r++) {
            float *cr = c + (size_t)r * n;
            __m256 v0 = acc[r][0], v1 = acc[r][1];
            if (!first) {
                v0 = _mm256_add_ps(v0, _mm256_loadu_ps(cr));
                v1 = _mm256_add_ps(v1, _mm256_loadu_ps(cr + 8));
            }
            _mm256_storeu_ps(cr, v0);
            _mm256_storeu_ps(cr + 8, v1);
        }
    } else {
        float tmp[MR][NR] __attribute__((aligned(32)));
#pragma GCC unroll 6
        for (int r = 0; r < MR; r++) {
            _mm256_store_ps(&tmp[r][0], acc[r][0]);
            _mm256_store_ps(&tmp[r][8], acc[r][1]);
        }
        for (int r = 0; r < mr; r++) {
            float *cr = c + (size_t)r * n;
            if (first)
                for (int j = 0; j < nr; j++) cr[j] = tmp[r][j];
            else
                for (int j = 0; j < nr; j++) cr[j] += tmp[r][j];
        }
    }
}
#else
static void kern(int kc, const float *restrict a, const float *restrict b,
                 float *restrict c, int n, int mr, int nr, int first)
{
    float acc[MR][NR];
    memset(acc, 0, sizeof(acc));
    for (int k = 0; k < kc; k++) {
        for (int r = 0; r < MR; r++) {
            float av = a[r];
            for (int j = 0; j < NR; j++) acc[r][j] += av * b[j];
        }
        a += MR;
        b += NR;
    }
    for (int r = 0; r < mr; r++) {
        float *cr = c + (size_t)r * n;
        if (first)
            for (int j = 0; j < nr; j++) cr[j] = acc[r][j];
        else
            for (int j = 0; j < nr; j++) cr[j] += acc[r][j];
    }
}
#endif

static void packA(const float *restrict A, float *restrict dst, int n, int p)
{
    int i0 = p * MR;
    for (int r = 0; r < MR; r++) {
        int i = i0 + r;
        if (i < n) {
            const float *src = A + (size_t)i * n;
            for (int k = 0; k < n; k++) dst[(size_t)k * MR + r] = src[k];
        } else {
            for (int k = 0; k < n; k++) dst[(size_t)k * MR + r] = 0.0f;
        }
    }
}

static void packB(const float *restrict B, float *restrict dst, int n, int q)
{
    int j0 = q * NR;
    int w = n - j0 < NR ? n - j0 : NR;
    for (int k = 0; k < n; k++) {
        const float *src = B + (size_t)k * n + j0;
        float *d = dst + (size_t)k * NR;
        if (w == NR) {
            for (int j = 0; j < NR; j++) d[j] = src[j];
        } else {
            for (int j = 0; j < w; j++) d[j] = src[j];
            for (int j = w; j < NR; j++) d[j] = 0.0f;
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int mp = (n + MR - 1) / MR;
    int np = (n + NR - 1) / NR;
    Abuf = ensure(Abuf, &Acap, (size_t)mp * MR * n);
    Bbuf = ensure(Bbuf, &Bcap, (size_t)np * NR * n);
    float *Ap = Abuf, *Bp = Bbuf;

    int nth = omp_get_max_threads();
    if (n < 96) nth = 1;
    int ncp = NCW / NR;
    if (ncp < 1) ncp = 1;
    int ntn = (np + ncp - 1) / ncp;
    int mpt = (int)((long)mp * ntn / (4L * nth));
    if (mpt < 1) mpt = 1;
    if (mpt > 8) mpt = 8;
    int ntm = (mp + mpt - 1) / mpt;
    int ntasks = ntm * ntn;

#pragma omp parallel if (n >= 96)
    {
#pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < mp + np; t++) {
            if (t < mp)
                packA(A, Ap + (size_t)t * MR * n, n, t);
            else
                packB(B, Bp + (size_t)(t - mp) * NR * n, n, t - mp);
        }

#pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < ntasks; t++) {
            int tm = t / ntn, tn = t % ntn;
            int p0 = tm * mpt, p1 = p0 + mpt < mp ? p0 + mpt : mp;
            int q0 = tn * ncp, q1 = q0 + ncp < np ? q0 + ncp : np;
            for (int pc = 0; pc < n; pc += KC) {
                int kc = n - pc < KC ? n - pc : KC;
                for (int p = p0; p < p1; p++) {
                    const float *ap = Ap + (size_t)p * MR * n + (size_t)pc * MR;
                    int mr = n - p * MR < MR ? n - p * MR : MR;
                    float *cp = C + (size_t)p * MR * n;
                    for (int q = q0; q < q1; q++) {
                        const float *bp = Bp + (size_t)q * NR * n + (size_t)pc * NR;
                        int nr = n - q * NR < NR ? n - q * NR : NR;
                        kern(kc, ap, bp, cp + q * NR, n, mr, nr, pc == 0);
                    }
                }
            }
        }
    }
}
